const input = $input.first().json;
const body = input.body || input;
const cf = body.custom_fields || body;

const firstName = body.first_name || cf.first_name || '';
const lastName = body.last_name || cf.last_name || '';
const phone = body.phone || cf.phone || '';
const email = body.email || cf.email || '';
const interest = body.interest || cf.interest || '';
const source = body.source || cf.source || '';
const dateAdded = new Date().toISOString();

if (!firstName && !lastName && !phone && !email) {
  return [{
    json: {
      success: false,
      error: 'No lead data received — all fields empty'
    }
  }];
}

// PII note: values array intentionally contains lead PII since it IS the
// data being written to Google Sheets. W1's PII scrub strips key-matched
// fields from payload_data but values[] passes through by design.
const wardenPayload = {
  requesting_agent: 'ManyChat Lead Capture Agent',
  target_service: 'Google_Sheets',
  payload_data: {
    operation: 'append',
    spreadsheet_id: $env.CNY_SHEET_ID || 'SHEET_ID_NOT_SET',
    range: 'Pre-Launch List!A:H',
    values: [firstName, lastName, phone, email, interest, source, dateAdded, 'New'],
    interest: interest,
    source: source,
    date_added: dateAdded,
    status: 'New'
  }
};

const wardenUrl = $env.N8N_BASE_URL + '/webhook/warden/intake';

try {
  const response = await fetch(wardenUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Warden-Token': $env.WARDEN_SECRET
    },
    body: JSON.stringify(wardenPayload)
  });

  const result = await response.json();

  if (response.status === 200) {
    return [{
      json: {
        success: true,
        message: 'Lead submitted to Warden for approval',
        transaction_id: result.transaction_id,
        status: result.status,
        lead: `${firstName} ${lastName}`.trim(),
        interest: interest
      }
    }];
  } else if (response.status === 409) {
    return [{
      json: {
        success: true,
        message: 'Duplicate lead — already submitted',
        existing_id: result.existing_id || result.transaction_id
      }
    }];
  } else {
    return [{
      json: {
        success: false,
        error: result.error || `Warden returned HTTP ${response.status}`
      }
    }];
  }
} catch (err) {
  return [{
    json: {
      success: false,
      error: `Failed to reach Warden: ${err.message}`
    }
  }];
}
